SELECT COUNT(*) AS matched, SUM(CASE WHEN p.amount <> d.amount OR (p.amount IS NULL) <> (d.amount IS NULL) THEN 1 ELSE 0 END) AS differing, SUM(CASE WHEN d.amount IS NULL THEN 1 ELSE 0 END) AS dev_null FROM prod.orders p JOIN db.orders d ON p.id = d.id;
SELECT COUNT(*) AS ids, COUNT(DISTINCT id) AS distinct_ids FROM db.orders;
SELECT COUNT(*) AS prod_only FROM prod.orders p WHERE NOT EXISTS (SELECT 1 FROM db.orders d WHERE d.id = p.id);

